script.text:

function load$Grid(g) {
	g.add_onResponseComplete(on$GridDomesticPurchaseInvoice$ResponseComplete);
	g.add_commandEvent(on$GridDomesticPurchaseInvoice$ExecuteCommand);
	&ddScriptGridLoad;
	&MultiViewer.Loading;
}
function dispose$Grid(g) {
	&MultiViewer.Dispose.Script;
	try {g.remove_commandEvent(on$GridDomesticPurchaseInvoice$ExecuteCommand);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridDomesticPurchaseInvoice$ResponseComplete);} catch (ex) {}
	&ddScriptGridDispose;
}
function on$GridDomesticPurchaseInvoice$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender;
	switch (action) {
		case 'ImportData':
			show$Form(g, 'PVMasterImport');
			break;
		case 'Download':
			&UserDefinedDownload;
			break;
		&QueryExecuteCommand;
		case 'AfterRemoveRow':
			&MultiViewer.AfterRemoveRow;
			break;
		&MultiViewer.RowColChange;
		default:
			break;
	}
}
function on$GridDomesticPurchaseInvoice$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object;
	switch (context) {
		case 'Download':
			g._key = result[0].Value;
			break;
		&ddScriptGridResponseComplete;
		default:
			break;
	}
}
&ddScriptGridRender;
function show$Form(g, c) {
	(g._authorize == 1) && (!g._denyNew) ? g.showForm(c) : $message.show(g._denyMessage ? g._denyMessage : $df.getResources(g._language, "Message.NotAccess"));
}

			&QueryScript;
			&DowloadScript;
			&PrintRightScript;
			&FlowMultiScript;
			&VisibleFieldScript;
			&MultiViewer.Script;
